interface.definition:
a!localVariables(
  local!loggedInUser:loggedInUser(),
  local!email:#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052922"(user:local!loggedInUser,property: "email"),
  local!refType:property(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050107"(
    refType: "User Role Type",
    columns: {"refTypeId"}
  ).data,"refTypeId",null),
  local!roles: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId: local!refType,
    returnCDT: false,
    columns: {
      "refId",
      "description"
    },
    isActive:true
  ).data,
  local!selectedRole,
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: "",
    contents: {
      #"SYSTEM_SYSRULES_sideBySideLayout"(
        items: {
          #"SYSTEM_SYSRULES_sideBySideItem"(
            item: #"SYSTEM_SYSRULES_imageField_v1"(
              label: "Image",
              labelPosition: "COLLAPSED",
              images: {
                #"SYSTEM_SYSRULES_userImage"(user: loggedInUser())
              },
              size: "MEDIUM",
              isThumbnail: false,
              style: "AVATAR"
            ),
            width: "MINIMIZE"
          ),
          #"SYSTEM_SYSRULES_sideBySideItem"(
            item: #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Rich Text",
              labelPosition: "COLLAPSED",
              value: {
                char(10),
                #"SYSTEM_SYSRULES_richTextItem_v1"(
                  text: "Welcome, "&user(loggedInUser(),"firstName")&" "&user(loggedInUser(),"lastName"),
                  color: #"_a-0000e48a-afd4-8000-9bb7-011c48011c48_549733"[1],
                  size: "LARGE",
                  style: "STRONG"
                )

              },
              align: "LEFT"
            )
          )
        }
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        divider: "ABOVE"
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: "By clicking confirm, your request will be submitted for approval to get access to CAW application."
          ))
      ),
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: {
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items:{ 
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_textField"(
                  label: "User Name",
                  value: local!loggedInUser,
                  readOnly: true,
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!loggedInUser))
                )
              ),
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_textField"(
                  label: "Email",
                  value: local!email,
                  readOnly: true,
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!loggedInUser))
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_sideBySideLayout"(
            items:{ 
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_textField"(
                  label: "Full Name",
                  value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(local!loggedInUser),
                  readOnly: true,
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!loggedInUser))
                )
              ),
              #"SYSTEM_SYSRULES_sideBySideItem"(
                item: #"SYSTEM_SYSRULES_dropdownField_v1"(
                  label: "Role Type:",
                  required: true,
                  choiceLabels: property(local!roles,"description",null),
                  choiceValues: property(local!roles,"refId",null),
                  value: local!selectedRole,
                  saveInto: {
                    local!selectedRole,
                    if(
                      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!selectedRole),
                      {
                        a!save(
                          local!selectedRole,
                          null
                        ),
                        a!save(
                          ri!user.roleId,
                          null
                        )
                      },
                      null
                    )
                  },
                  placeholder: "Select a Role Type",
                  showWhen: not(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!loggedInUser))
                )
              ),
            }
          )
        }
      ),
    }
  )
)
